def known_by(docs, t):
    return [d for d in docs if d['published'] <= t]


def asof_feature(docs, days, decision_time):
    out = []
    for day in days:
        k = known_by(docs, day + ' ' + decision_time)
        out.append(k[-1]['score'] if k else None)
    return out

def known_by(docs, t):
    return [d for d in docs if d['published'] <= t]


def asof_feature(docs, days, decision_time):
    out = []
    for day in days:
        k = known_by(docs, day + ' ' + decision_time)
        out.append(max(k, key=lambda d: d['published'])['score'] if k else 0.0)
    return out
